            // Re-attach canvas handlers whenever tool changes so Wand/Spatial/Brush/etc. always work
            // (handlers can be missing if paint was shown without going through a load path)
            if (canvas && canvas.width && canvas.height && typeof paintImageData !== 'undefined' && paintImageData) {
                setupCanvasHandlers(canvas);
            }
            _resetToolOptionsRail();
            // SPB-93 2026-09-07, owner: no "weird lag drags". Refresh after
            // the new options are visible: a stale collapsed rail otherwise
            // opens on the first Rectangle move and removes 78px mid-gesture.
            // Keep the owner-frozen Pick Color activation path unchanged.
            if (mode !== 'eyedropper' && typeof renderContextActionBar === 'function') renderContextActionBar();
