        // of Photoshop-natural. Before -> after: Shift+click made 1 isolated dab
        // -> it connects the previous endpoint to the new one on the same target.
        var _lastBrushStrokeAnchor = null;
        var _brushStrokeEndpoint = null;

        function _getBrushStrokeTargetKey() {
            if (typeof isLayerPaintMode === 'function' && isLayerPaintMode()) {
                const layer = (typeof getSelectedEditableLayer === 'function') ? getSelectedEditableLayer() : null;
                return layer ? `layer:${layer.id}` : null;
            }
            return (typeof selectedZoneIndex === 'number') ? `zone:${selectedZoneIndex}` : null;
        }

        function _getBrushLineAnchor(mode) {
            const targetKey = _getBrushStrokeTargetKey();
            if (!_lastBrushStrokeAnchor || !targetKey) return null;
            if (_lastBrushStrokeAnchor.mode !== mode || _lastBrushStrokeAnchor.targetKey !== targetKey) return null;
            return { x: _lastBrushStrokeAnchor.x, y: _lastBrushStrokeAnchor.y };
        }

        function _forEachBrushLineDab(start, end, radius, paintDab) {
            if (!start || !end || typeof paintDab !== 'function') return 0;
            const dx = end.x - start.x, dy = end.y - start.y;
            const distance = Math.hypot(dx, dy);
            const spacingPct = parseInt(document.getElementById('brushSpacing')?.value || 25);
            const minDist = Math.max(1, radius * spacingPct / 100);
            const steps = Math.max(1, Math.ceil(distance / minDist));
            for (let i = 0; i <= steps; i++) {
                const t = i / steps;
                paintDab(start.x + dx * t, start.y + dy * t);
            }
            return steps + 1;
        }

        // SPB-93 Pass 105 (2026-07-17): one opening-dab contract for every
        // paint/retouch tool. Shift+click connects from the last committed
        // endpoint only when mode + Layer/Zone target still match.
        function _paintOpeningWithShiftLine(event, point, radius, paintDab) {
            if (!point || typeof paintDab !== 'function') return null;
            const anchor = event?.shiftKey ? _getBrushLineAnchor(canvasMode) : null;
            if (anchor) _forEachBrushLineDab(anchor, point, radius, paintDab);
            else paintDab(point.x, point.y);
            _rememberBrushStrokeEndpoint(point.x, point.y, canvasMode);
            return anchor;
        }

        function _rememberBrushStrokeEndpoint(x, y, mode) {
            const targetKey = _getBrushStrokeTargetKey();
            if (!targetKey) return;
            _brushStrokeEndpoint = { x, y, mode, targetKey };
        }

        function _commitBrushStrokeAnchor() {
            if (!_brushStrokeEndpoint) return;
            _lastBrushStrokeAnchor = { ..._brushStrokeEndpoint };
            _brushStrokeEndpoint = null;
        }
        function _checkBrushSpacing(x, y, radius) {
            const spacingPct = parseInt(document.getElementById('brushSpacing')?.value || 25);
            const minDist = Math.max(1, radius * spacingPct / 100);
            const dx = x - _lastDabX, dy = y - _lastDabY;
            if (dx * dx + dy * dy >= minDist * minDist) {
                _lastDabX = x; _lastDabY = y;
                return true;
            }
            return false;
        }
        function _currentBrushPressure() {
            return (typeof window._lastPointerPressure === 'number') ? window._lastPointerPressure : 1;
        }
        function _filterContinuousBrushPoint(point) {
            if (!point) return null;
            let filtered = { x: point.x, y: point.y };
            if (typeof window.smoothBrushPoint === 'function') {
                const smoothed = window.smoothBrushPoint(filtered.x, filtered.y);
                filtered = { x: smoothed.x, y: smoothed.y };
            }
            if (typeof window.stabilizeBrushPoint === 'function') {
                const stabilized = window.stabilizeBrushPoint(filtered.x, filtered.y);
                filtered = { x: stabilized.x, y: stabilized.y };
            }
            return filtered;
        }
        function _seedBrushSpacing(x, y, pressure) {
            _lastDabX = x;
            _lastDabY = y;
            _brushSpacingState = window.SPBStrokeDynamics?.beginStroke
                ? window.SPBStrokeDynamics.beginStroke({ x, y, pressure })
                : null;
        }
        // SPB-93 Pass 47 (2026-07-17), owner verdict: all toolbar tools must
        // feel natural. Every brush-family stroke now starts with fresh input
        // filters and an explicit spacing seed, so a prior stroke cannot tug,
        // skip, or double-stamp the opening movement of the next stroke.
        function _beginContinuousBrushStroke(point) {
            _resetBrushSpacing();
            if (typeof window.resetBrushSmoothing === 'function') window.resetBrushSmoothing();
            if (typeof window.resetBrushStabilizer === 'function') window.resetBrushStabilizer();
            const filtered = _filterContinuousBrushPoint(point);
            if (filtered) _seedBrushSpacing(filtered.x, filtered.y, _currentBrushPressure());
            return filtered;
        }
        function _paintContinuousBrushDab(dab, paintDab) {
            const priorPressure = window._lastPointerPressure;
            window._lastPointerPressure = Number.isFinite(Number(dab?.pressure)) ? Number(dab.pressure) : 1;
            try {
                paintDab({ ...dab, x: Math.round(Number(dab?.x) || 0), y: Math.round(Number(dab?.y) || 0) });
            } finally {
                window._lastPointerPressure = priorPressure;
            }
        }
        function _paintContinuousBrushDabs(points, paintDab) {
            if (!Array.isArray(points) || points.length === 0) return 0;
            // Pass 47: distance resampling can emit many dabs from one fast
            // pointer event. Defer full-canvas putImageData until the segment
            // is complete: N uploads per event -> 1, while all pixel math and
            // per-dab pressure remain identical.
            window._spbPaintFlushBatchDepth = (Number(window._spbPaintFlushBatchDepth) || 0) + 1;
            try {
                for (const point of points) _paintContinuousBrushDab(point, paintDab);
            } finally {
                window._spbPaintFlushBatchDepth = Math.max(0, (Number(window._spbPaintFlushBatchDepth) || 1) - 1);
                if (window._spbPaintFlushBatchDepth === 0 && window._spbPaintFlushPending) {
                    window._spbPaintFlushPending = false;
                    if (typeof _flushPaintImageDataToCurrentSurface === 'function') _flushPaintImageDataToCurrentSurface();
                }
            }
            return points.length;
        }
