            // while typing in a text input (e.g. zone-name rename) would
            // deselect the painter's active layer instead of just cancelling
            // the input. Now gate on input focus, matching the Space key
            // guard already above.
            const _escTag = (e.target && e.target.tagName || '').toLowerCase();
            const _escIsInput = _escTag === 'input' || _escTag === 'textarea' || _escTag === 'select'
                || (e.target && e.target.isContentEditable);
            if (e.key === 'Escape' && !_escIsInput && typeof _selectionMoveDrag !== 'undefined' && _selectionMoveDrag) {
                if (typeof cancelSelectionMove === 'function') cancelSelectionMove(false);
                e.preventDefault();
                return;
            }
            // 2026-06-05 (later 44) owner /loop "make transform seamless like Photoshop": when a
            // free-transform is ACTIVE, Esc must CANCEL the transform (the handler at ~L13348 ->
