    const isTransformTarget = (s.target === 'layer') || (typeof _isZoneFreeTransformTarget === 'function' && _isZoneFreeTransformTarget(s.target));
    const hasOrigCenter = s.origCenterX !== undefined;
    const moved = hasOrigCenter && Math.hypot(s.centerX - s.origCenterX, s.centerY - s.origCenterY) > 3;

    const customPivotActive = isTransformTarget && hasOrigCenter && Math.hypot(s.centerX - s.origCenterX, s.centerY - s.origCenterY) > 3;

    ctx.strokeStyle = customPivotActive ? '#ff88cc' : '#00e5ff';
    ctx.lineWidth = customPivotActive ? 2.5 : 2;
    if (customPivotActive) ctx.setLineDash([4, 3]); // dashed stem when custom pivot (SPB-93 Track 1)
    ctx.beginPath();
    ctx.moveTo(tm.x, tm.y);
    ctx.lineTo(rotPtPos.x, rotPtPos.y);
    ctx.stroke();
    if (customPivotActive) ctx.setLineDash([]);
    ctx.beginPath();
    ctx.arc(rotPtPos.x, rotPtPos.y, customPivotActive ? 8 : 7, 0, Math.PI * 2);
    ctx.fillStyle = customPivotActive ? '#ff88cc' : '#00e5ff';
    ctx.fill();
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = customPivotActive ? 2 : 1.5;
    ctx.stroke();

