    ctx.lineWidth = pivotLineWidth;
    ctx.beginPath();
    ctx.moveTo(cx - pivotSize, cy);
    ctx.lineTo(cx + pivotSize, cy);
    ctx.moveTo(cx, cy - pivotSize);
    ctx.lineTo(cx, cy + pivotSize);
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(cx, cy, isDraggingPivot ? 6.5 : (pivotActive ? 5 : (moved ? 4 : 3)), 0, Math.PI * 2);
    ctx.strokeStyle = isDraggingPivot ? '#ff99cc' : (pivotActive ? '#ffbbdd' : (moved ? '#ff99bb' : '#ff3366'));
