        const scaleVal = Math.round(((s.scaleX || 1) + (s.scaleY || 1)) / 2 * 100);
        const posX = Math.round(s.centerX);
        const posY = Math.round(s.centerY);
        let extra = '';
        if (s.localPivotDeltaX !== undefined && s.localPivotDeltaY !== undefined) {
            const lpx = Math.round(s.localPivotDeltaX);
            const lpy = Math.round(s.localPivotDeltaY);
            if (Math.abs(lpx) > 1 || Math.abs(lpy) > 1) extra = `  LocalPivot ${lpx},${lpy}`;
        }

        const isLayerElement = (s.target === 'layer' && s.subRect);
        const isZoneSubPiece = (typeof s.target === 'string' && _isZoneFreeTransformTarget(s.target) && s.subRect);
        const prefix = isLayerElement ? 'Element ' : (isZoneSubPiece ? 'Sub-Piece ' : (s.target === 'layer' ? 'Layer ' : ''));

        // SPB-93 v57: Prominent live numeric feedback for Zone transforms (parity with Layer quickbar HUD)
