            ctx.bezierCurveTo(ccx, oy + sh * 0.8, ox + sw, oy + sh * 0.6, ox + sw, oy + sh * 0.35);
            ctx.bezierCurveTo(ox + sw, oy, ccx, oy, ccx, oy + sh * 0.35); ctx.closePath();
