            const hr = Math.min(sw, sh) / 2;
            for (let i = 0; i < 6; i++) { const a = (i / 6) * Math.PI * 2 - Math.PI / 6; ctx.lineTo(ccx + hr * Math.cos(a), ccy + hr * Math.sin(a)); }
            ctx.closePath();
