            const or2 = Math.min(sw, sh) / 2;
            for (let i = 0; i < 8; i++) { const a = (i / 8) * Math.PI * 2 - Math.PI / 8; ctx.lineTo(ccx + or2 * Math.cos(a), ccy + or2 * Math.sin(a)); }
