            ctx.lineTo(ox + w6 * 3.5, oy + h4); ctx.lineTo(ox + w6 * 5, oy + h4 * 2.5);
            ctx.lineTo(ox + w6 * 3, oy + h4 * 2.5); ctx.lineTo(ox + w6 * 4.5, oy + sh);
