        ctx.fillStyle = '#fff';
        ctx.strokeStyle = '#00e5ff';
        ctx.lineWidth = guideScale;
        ctx.fillRect(p.x - anchorHalf, p.y - anchorHalf, anchorHalf * 2, anchorHalf * 2);
        ctx.strokeRect(p.x - anchorHalf, p.y - anchorHalf, anchorHalf * 2, anchorHalf * 2);
