        if (Math.hypot(p.cx1 - p.x, p.cy1 - p.y) > handleThreshold) {
            ctx.strokeStyle = 'rgba(0,229,255,0.5)';
            ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p.cx1, p.cy1); ctx.stroke();
            ctx.fillStyle = '#00e5ff';
            ctx.beginPath(); ctx.arc(p.cx1, p.cy1, handleRadius, 0, Math.PI * 2); ctx.fill();
        }
        if (Math.hypot(p.cx2 - p.x, p.cy2 - p.y) > handleThreshold) {
            ctx.strokeStyle = 'rgba(0,229,255,0.5)';
            ctx.beginPath(); ctx.moveTo(p.x, p.y); ctx.lineTo(p.cx2, p.cy2); ctx.stroke();
            ctx.fillStyle = '#00e5ff';
            ctx.beginPath(); ctx.arc(p.cx2, p.cy2, handleRadius, 0, Math.PI * 2); ctx.fill();
        }
