    // forces hardness = 1.0 (binary edges, no anti-aliasing — that's what
    // distinguishes "pencil" from "brush" in Photoshop). Previous version
    // was a single-pixel toy regardless of size.
    // 2026-06-20: optional skipFlush lets _pencilStrokeTo() stamp a whole
    // interpolated segment and flush ONCE at the end (avoids N GPU uploads).
    const pc = document.getElementById('paintCanvas');
    if (!pc || !paintImageData) return;
    const w = pc.width, h = pc.height, d = paintImageData.data;
    const requestedSize = Math.max(1, parseInt(document.getElementById('brushSize')?.value || 1));
    const opacityBase = parseInt(document.getElementById('brushOpacity')?.value || 100) / 100;
    const flow = parseInt(document.getElementById('brushFlow')?.value || 100) / 100;
    const pencilDynamics = _resolveBrushDynamics(requestedSize, opacityBase, flow);
