            const selectionCoverage = _selectionCoverage(_rmask, py * w + px);
            if (selectionCoverage <= 0) continue;
            const idx = (py * w + px) * 4;
            const sourceIdx = ((py - patch.y0) * patch.width + (px - patch.x0)) * 4;
            if (src[sourceIdx + 3] === 0) continue;
