    const cssRect = rc.getBoundingClientRect();
    const zoom = cssRect.width > 0 ? cssRect.width / rc.width : 1;
    const guideScale = 1 / Math.max(0.001, zoom);

    ctx.save();
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = Math.max(1, guideScale * 1.25);
