    try { if (typeof _activeLayerCtx !== 'undefined') _activeLayerCtx = null; } catch (_) {}
    try { if (typeof _savedPaintImageData !== 'undefined') _savedPaintImageData = null; } catch (_) {}
    try { if (typeof _lockedLayerWarnedFor !== 'undefined') _lockedLayerWarnedFor = null; } catch (_) {}
