function _spbSnapshotCanvas(canvas) {
    if (!canvas) return null;
    const snapshot = { width: canvas.width || 0, height: canvas.height || 0, pixels: null };
    if (!snapshot.width || !snapshot.height) return snapshot;
    try {
        snapshot.pixels = new Uint8ClampedArray(
            canvas.getContext('2d', { willReadFrequently: true })
                .getImageData(0, 0, snapshot.width, snapshot.height).data
        );
    } catch (_) {}
    return snapshot;
}

function _spbRestoreCanvasSnapshot(canvas, snapshot) {
    if (!canvas || !snapshot) return;
    canvas.width = snapshot.width;
    canvas.height = snapshot.height;
    if (!snapshot.pixels || !snapshot.width || !snapshot.height) return;
    const ctx = canvas.getContext('2d', { willReadFrequently: true });
    const restored = ctx.createImageData(snapshot.width, snapshot.height);
    restored.data.set(snapshot.pixels);
    ctx.putImageData(restored, 0, 0);
}

