        opacity: layer.opacity != null ? layer.opacity : 255,
        img: layer.img, // shares the Image reference (immutable)
        bbox: Array.isArray(layer.bbox) ? [...layer.bbox] : [0, 0, fallbackWidth, fallbackHeight],
        groupName: layer.groupName || '',
        groupChain: Array.isArray(layer.groupChain) ? JSON.parse(JSON.stringify(layer.groupChain)) : [],
        parentGroupKey: layer.parentGroupKey || null,
