        bbox: newBbox,
        groupName: layer.groupName || '',
        groupChain: Array.isArray(layer.groupChain) ? JSON.parse(JSON.stringify(layer.groupChain)) : [],
        parentGroupKey: layer.parentGroupKey || null,
        blendMode: layer.blendMode || 'source-over',
        locked: false,
        alphaLock: !!layer.alphaLock,
        clippingMask: !!layer.clippingMask,
