    for (let i = _psdLayers.length - 1; i >= 0; i--) { if (ids.has(_psdLayers[i].id)) _psdLayers.splice(i, 1); }
    _selectedLayerIds = new Set();
    _selectedLayerId = _psdLayers.length ? _psdLayers[_psdLayers.length - 1].id : null;
    if (typeof window !== 'undefined') window._selectedLayerId = _selectedLayerId;
    recompositeFromLayers();
    renderLayerPanel();
    if (typeof triggerPreviewRender === 'function') triggerPreviewRender();
