        try { const _c = document.getElementById('paintCanvas'); const _r = _c.getBoundingClientRect(); if (_r.width) sx = _c.width / _r.width; } catch (_) {}
        if (Math.hypot(dx, dy) / sx < 5) return;   // within ~5 screen-px dead-zone → ignore (no move, no undo, no toast)
        if (typeof _pushLayerStackUndo === 'function') _pushLayerStackUndo('move layer');
