                    const instSrcY = inst.instanceBbox.y1 - origin.y;
                    const instSrcW = Math.abs(inst.instanceBbox.x2 - inst.instanceBbox.x1);
                    const instSrcH = Math.abs(inst.instanceBbox.y2 - inst.instanceBbox.y1);

