                // Union AABB so a glyph dragged/rotated beyond the source still fits.
                const ux1 = Math.min(sx1, tx1), uy1 = Math.min(sy1, ty1);
                const ux2 = Math.max(sx2, tx2), uy2 = Math.max(sy2, ty2);
                const uW = Math.max(1, Math.round(ux2 - ux1));
                const uH = Math.max(1, Math.round(uy2 - uy1));
