function _ctxSelectAll() {
    var z = zones[selectedZoneIndex];
    if (!z) return false;
    var pc = document.getElementById('paintCanvas');
    if (!pc) return false;
    var size = pc.width * pc.height;
    var alreadyFull = !!(z.regionMask && z.regionMask.length === size);
    for (var index = 0; alreadyFull && index < size; index++) {
        if (z.regionMask[index] !== 255) alreadyFull = false;
    }
    if (alreadyFull) {
        if (typeof showToast === 'function') showToast('All canvas pixels are already selected');
        return false;
    }
    if (typeof window._spbPushZoneMaskUndoSnapshot !== 'function') {
        if (typeof showToast === 'function') showToast('Select All history is unavailable - reload the booth');
        return false;
    }
    // SPB-93 tick 29, owner verdict: tools must do what they claim. Served QA
    // proved the old config-history call toasted Undo but left 4,194,304 pixels
    // selected. Snapshot the actual Zone mask only after no-op validation.
    window._spbPushZoneMaskUndoSnapshot(selectedZoneIndex);
    z.regionMask = new Uint8Array(size);
    z.regionMask.fill(255);
    if (typeof renderRegionOverlay === 'function') renderRegionOverlay();
    if (typeof updateRegionStatus === 'function') updateRegionStatus();
    if (typeof renderContextActionBar === 'function') renderContextActionBar();
    if (typeof renderZones === 'function') renderZones();
    if (typeof triggerPreviewRender === 'function') triggerPreviewRender();
    if (typeof showToast === 'function') showToast('Selected all pixels in Zone ' + (selectedZoneIndex + 1));
    return true;
}
function _ctxTransform() { if (typeof activateContextTransform === 'function') activateContextTransform(); }
function _ctxZoomFit() { if (typeof canvasZoom === 'function') canvasZoom('fit'); }
function _ctxZoom100() { if (typeof canvasZoom === 'function') canvasZoom('100'); }

// v111: Helper for Element Link Groups
function _getLayerElementGroup(layer, bbox) {
    if (!layer || !layer.elementLinkGroups || !bbox) return null;
    for (const group of layer.elementLinkGroups) {
        for (const member of group) {
            if (member.x1 === bbox.x1 && member.y1 === bbox.y1 && member.x2 === bbox.x2 && member.y2 === bbox.y2) {
                return group;
            }
        }
    }
    return null;
}

function _getElementInstances(layer, sourceBbox) {
    return window.SPBElementInstances?.linked(layer, sourceBbox) || [];
}

// v117: Parallel helper for Zone Pattern Instances (dual-track parity)
function _getZonePatternInstances(zone, sourceBbox) {
    if (!zone || !zone.patternInstances || !sourceBbox) return [];
    return zone.patternInstances.filter(inst =>
        !inst.detached && inst.sourceBbox && sourceBbox &&
        inst.sourceBbox.x1 === sourceBbox.x1 && inst.sourceBbox.y1 === sourceBbox.y1 &&
        inst.sourceBbox.x2 === sourceBbox.x2 && inst.sourceBbox.y2 === sourceBbox.y2
    );
}

// v139: Centralized helper to apply an instance snapshot to a specPatternStack entry.
// This ensures all paths (commit, Promote, Re-apply, color tools) produce consistent data for the core renderer.
function _applyInstanceSnapshotToSpecPatternEntry(sp, snapshot) {
    if (!sp || !snapshot) return;
    sp.instanceSourceSnapshot = snapshot;
    sp.instanceSnapshotData = snapshot;
    sp.useInstanceSnapshot = true;
    sp.lastInstanceSnapshotUpdate = Date.now();
}

function _computeGroupUnion(group) {
    if (!group || group.length === 0) return null;
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    for (const m of group) {
        minX = Math.min(minX, m.x1);
        minY = Math.min(minY, m.y1);
        maxX = Math.max(maxX, m.x2);
        maxY = Math.max(maxY, m.y2);
    }
    return { x1: minX, y1: minY, x2: maxX, y2: maxY };
}

// v110: First prototype of Element Link Groups – high-leverage new tool for Shokker Paint Booth
// Allows users to link multiple discrete elements (sponsors, numbers, logos) inside the same PSD layer
// so they transform together as a unit while remaining individually editable. This is extremely powerful
// for real livery work with complex sponsor clusters.
function _ctxLinkWithPreviousElement() {
    const layer = getSelectedLayer();
    if (!layer || !freeTransformState || !freeTransformState.subRect || freeTransformState.target !== 'layer') return;

    const current = window._spbLastPickedElementBbox || (freeTransformState.subRect ? { ...freeTransformState.subRect, layerId: layer.id } : null);
    const prev = window._spbPreviousPickedElementBbox;

    if (!current || !prev) {
        if (typeof showToast === 'function') showToast('Need two elements to link (pick another first)', 'info');
        return;
    }

    if (!layer.elementLinkGroups) layer.elementLinkGroups = [];

    // Create a new group containing both (use a simple deep copy of the bboxes)
    const group = [JSON.parse(JSON.stringify(current)), JSON.parse(JSON.stringify(prev))];
    layer.elementLinkGroups.push(group);

    if (typeof showToast === 'function') showToast('Elements linked into a group – they will now transform together', 'success');

    // One-time discoverability toast
    if (typeof window !== 'undefined' && !window._spbShownLinkGroupsToast) {
        window._spbShownLinkGroupsToast = true;
        if (typeof showToast === 'function') {
            setTimeout(() => {
                showToast('New: Linked Element Groups – transform multiple sponsors/numbers as one unit while keeping them individually editable. Right-click for more options.', 'info');
            }, 800);
        }
    }

    drawTransformHandles();
    if (typeof renderContextActionBar === 'function') renderContextActionBar();
}

function _ctxSelectGroup() {
    const layer = getSelectedLayer();
    if (!layer || !layer.elementLinkGroups || !freeTransformState || freeTransformState.target !== 'layer' || !freeTransformState.subRect) return;

    const current = freeTransformState.subRect;
    let foundGroup = null;

    for (const g of layer.elementLinkGroups) {
        for (const member of g) {
            if (member.x1 === current.x1 && member.y1 === current.y1 && member.x2 === current.x2 && member.y2 === current.y2) {
                foundGroup = g;
                break;
            }
        }
        if (foundGroup) break;
    }

    if (!foundGroup) {
        if (typeof showToast === 'function') showToast('Current element is not in a group', 'info');
        return;
    }

    // For the prototype, just toast which members are linked. Real multi-selection would highlight all.
    if (typeof showToast === 'function') {
        showToast(`Group contains ${foundGroup.length} linked elements. Future: multi-select all members.`, 'info');
    }
}

function _ctxUnlinkCurrentElement() {
    const layer = getSelectedLayer();
    if (!layer || !layer.elementLinkGroups || !freeTransformState || freeTransformState.target !== 'layer' || !freeTransformState.subRect) return;

    const current = freeTransformState.subRect;
    let removed = false;

    for (let g = 0; g < layer.elementLinkGroups.length; g++) {
        const group = layer.elementLinkGroups[g];
        for (let i = 0; i < group.length; i++) {
            const m = group[i];
            if (m.x1 === current.x1 && m.y1 === current.y1 && m.x2 === current.x2 && m.y2 === current.y2) {
                group.splice(i, 1);
                removed = true;
                break;
            }
        }
        if (group.length <= 1) {
            layer.elementLinkGroups.splice(g, 1);
            g--;
        }
        if (removed) break;
    }

    if (removed && typeof showToast === 'function') {
        showToast('Element unlinked from group', 'success');
    }

    drawTransformHandles();
    if (typeof renderContextActionBar === 'function') renderContextActionBar();
}

// SPB-93: create a visible linked copy with independent placement and one Undo.
function _ctxCreateLinkedInstance() {
    const state = freeTransformState, layer = getSelectedLayer();
    if (!layer || layer.locked || state?.target !== 'layer' || !state.origSubRect) return;
    const frame = window.SPBElementTransformState.item(state, state.origSubRect);
    const rect = window.SPBLayerTransformRaster.transformedAabb(frame);
    commitLayerTransform();
    if (freeTransformState || !rect) return;
    const pc = document.getElementById('paintCanvas');
    const result = window.SPBElementInstances?.prepare(layer, rect, pc.width, pc.height, function(w,h) {
        const canvas = document.createElement('canvas'); canvas.width=w; canvas.height=h; return canvas;
    });
    if (!result) {
        if (typeof showToast === 'function') showToast('No empty space for this repeat on the Layer. Move existing artwork or use a new Layer.', 'warn');
        return;
    }
    _pushLayerUndo(layer, 'create linked instance');
    layer.img=result.canvas; layer.bbox=result.bbox; layer.elementInstances=result.instances;
    recompositeFromLayers(); renderLayerPanel();
    if (typeof triggerPreviewRender === 'function') triggerPreviewRender();
    if (typeof showToast === 'function') showToast('Linked copy created in empty Layer space. Pick the copy to move it; Ctrl+Z undoes creation.', 'success');
}

