    const masterInst = insts.find(i =>
        i.sourceBbox && i.sourceBbox.x1 === current.x1 && i.sourceBbox.y1 === current.y1 &&
        i.sourceBbox.x2 === current.x2 && i.sourceBbox.y2 === current.y2
    );
    const masterSnap = masterInst?.sourcePixelSnapshot || masterInst?.currentSyncedSnapshot || null;

    // Propagate snapshot + timestamps to the whole group (real data sync)
    for (const inst of insts) {
        if (masterSnap) {
            inst.sourcePixelSnapshot = masterSnap;
            inst.currentSyncedSnapshot = masterSnap;
        }
        inst.lastSyncedAt = now;
    }

    // v135: Also push the snapshot + explicit flag to the actual specPatternStack entry for the current piece
    const reapplyIdx = parseInt((freeTransformState.target || '').split('_').pop(), 10);
    if (!isNaN(reapplyIdx) && z.specPatternStack && z.specPatternStack[reapplyIdx] && masterSnap) {
        const reapplyEntry = z.specPatternStack[reapplyIdx];
        _applyInstanceSnapshotToSpecPatternEntry(reapplyEntry, masterSnap);
    }

    if (typeof showToast === 'function') {
        showToast(`Re-applied master source to ${insts.length} Zone pattern instance(s) (snapshot propagated)`, 'success');
    }

