// v120: Zone Promote (parity)
window._ctxPromoteZoneToMaster = function _ctxPromoteZoneToMaster() {
    if (_runZoneMaterialMasterCommand('promote')) return;
    const z = zones[selectedZoneIndex];
    if (!z || !freeTransformState || !freeTransformState.subRect) return;

    const insts = _getZonePatternInstances(z, freeTransformState.subRect);
    if (insts.length === 0) {
        if (typeof showToast === 'function') showToast('Current piece is not part of a pattern instance group', 'info');
        return;
    }

    pushZoneUndo('Promote Zone pattern master');
    const current = freeTransformState.subRect;
    const now = Date.now();

    // Find if the current piece has a snapshot (from creation or previous promote)
    const currentInst = z.patternInstances.find(inst =>
        inst.sourceBbox && inst.sourceBbox.x1 === current.x1 && inst.sourceBbox.y1 === current.y1 &&
        inst.sourceBbox.x2 === current.x2 && inst.sourceBbox.y2 === current.y2
    );
    const newMasterSnapshot = currentInst?.sourcePixelSnapshot || currentInst?.currentSyncedSnapshot || null;

    for (const inst of z.patternInstances) {
        const wasRelated = (inst.sourceBbox && inst.sourceBbox.x1 === current.x1 && inst.sourceBbox.y1 === current.y1 &&
                            inst.sourceBbox.x2 === current.x2 && inst.sourceBbox.y2 === current.y2) ||
                           (inst.instanceBbox && inst.instanceBbox.x1 === current.x1 && inst.instanceBbox.y1 === current.y1 &&
                            inst.instanceBbox.x2 === current.x2 && inst.instanceBbox.y2 === current.y2);
        if (wasRelated) {
            inst.sourceBbox = { ...current };
            inst.lastSyncedAt = now;
            inst.instanceBbox = { ...current };
            if (newMasterSnapshot) {
                inst.sourcePixelSnapshot = newMasterSnapshot;

                // v132: Also push the snapshot onto the actual specPatternStack entry for the promoted pattern
                const promotedIdx = parseInt((freeTransformState.target || '').split('_').pop(), 10);
                if (!isNaN(promotedIdx) && z.specPatternStack && z.specPatternStack[promotedIdx]) {
                    const promotedEntry = z.specPatternStack[promotedIdx];
                    _applyInstanceSnapshotToSpecPatternEntry(promotedEntry, newMasterSnapshot);
                }
            }
        }
    }

    // v123: If the current piece didn't have a snapshot yet but one exists in the group, copy it forward
    if (!newMasterSnapshot) {
        const anySnapshot = z.patternInstances.find(i => i.sourcePixelSnapshot || i.currentSyncedSnapshot);
        if (anySnapshot) {
            const snap = anySnapshot.sourcePixelSnapshot || anySnapshot.currentSyncedSnapshot;
            for (const inst of z.patternInstances) {
                if (inst.sourceBbox && inst.sourceBbox.x1 === current.x1 && inst.sourceBbox.y1 === current.y1 &&
                    inst.sourceBbox.x2 === current.x2 && inst.sourceBbox.y2 === current.y2) {
                    inst.sourcePixelSnapshot = snap;
                }
            }
        }
    }

    freeTransformState.sessionScopeLabel = `Sub-Piece: Pattern (Master Pattern Source – ${insts.length + 1} total)`;
    drawTransformHandles();

    if (typeof showToast === 'function') {
        showToast(`Promoted current pattern piece to Master Source for ${insts.length + 1} linked instances (snapshot propagated)`, 'success');
    }
};

