    if (!canvasRect.width || !canvasRect.height) return null;
    const viewport = document.getElementById('splitSource') || document.getElementById('canvasViewport');
    const viewportRect = viewport?.getBoundingClientRect ? viewport.getBoundingClientRect() : canvasRect;
    const windowWidth = (typeof window !== 'undefined' && window.innerWidth) ? window.innerWidth : viewportRect.right;
    const windowHeight = (typeof window !== 'undefined' && window.innerHeight) ? window.innerHeight : viewportRect.bottom;
    const left = Math.max(canvasRect.left, viewportRect.left, 0);
    const top = Math.max(canvasRect.top, viewportRect.top, 0);
