// Border selection — select only the border of the current selection
function borderSelection(width) {
    const context = _selectionRefineContext('No selection to border');
    if (!context) return false;
    const bw = Math.max(1, Math.min(64, parseInt(width, 10) || 3));
    const startedAt = performance.now();
    const outer = window.SPBSelectionRefine.morph(
        context.zone.regionMask, context.canvas.width, context.canvas.height, bw, 'grow'
    ).mask;
    const inner = window.SPBSelectionRefine.morph(
        context.zone.regionMask, context.canvas.width, context.canvas.height, bw, 'shrink'
    ).mask;
    const nextMask = new Uint8Array(outer.length);
    let changedPixels = 0;
    for (let i = 0; i < outer.length; i++) {
        const value = outer[i] > 0 && inner[i] === 0 ? 255 : 0;
        nextMask[i] = value;
        if (value !== context.zone.regionMask[i]) changedPixels++;
    }
    const result = {
        mask: nextMask,
        changedPixels,
        startedAt,
        computeMs: performance.now() - startedAt,
    };
    return _commitSelectionRefine(
        context, result,
        () => `Border selection: ${bw}px`,
        'Selection is already that border'
    );
}

// Select Color Range — select all pixels within a color range from FG color
function selectColorRange(tolerance) {
    const pc = document.getElementById('paintCanvas');
    if (!pc || !paintImageData) return false;
    const w = pc.width, h = pc.height;
    const zone = zones[selectedZoneIndex];
    if (!zone) return false;
    const parsedTolerance = parseInt(tolerance, 10);
    const tol = Number.isFinite(parsedTolerance)
        ? Math.max(0, Math.min(255, parsedTolerance))
        : 32;
    const fgHex = _foregroundColor;
    const tr = parseInt(fgHex.slice(1,3), 16), tg = parseInt(fgHex.slice(3,5), 16), tb = parseInt(fgHex.slice(5,7), 16);
    const tol2 = tol * tol * 3;
    const d = paintImageData.data;
    const candidate = new Uint8Array(w * h);
    let matchedPixels = 0;
    for (let i = 0; i < candidate.length; i++) {
        const idx = i * 4;
        const dr = d[idx] - tr, dg = d[idx+1] - tg, db = d[idx+2] - tb;
        if (dr*dr + dg*dg + db*db <= tol2) {
            candidate[i] = 255;
            matchedPixels++;
        }
    }
    const existing = zone.regionMask?.length === candidate.length
        ? zone.regionMask
        : new Uint8Array(candidate.length);
    const mode = document.getElementById('selectionMode')?.value || 'replace';
    const nextMask = new Uint8Array(candidate.length);
    let changedPixels = 0;
    for (let i = 0; i < candidate.length; i++) {
        let value = candidate[i];
        if (mode === 'add') value = Math.max(existing[i], candidate[i]);
        else if (mode === 'subtract') value = candidate[i] ? 0 : existing[i];
        nextMask[i] = value;
        if (value !== existing[i]) changedPixels++;
    }
    // SPB-93 tick 37, owner verdict: selection still felt "jinky/off."
    // Legacy Color Range pushed config history before mutation and only ever
    // added pixels. It now honors Replace/Add/Subtract and records one actual
    // mask snapshot only after a changed candidate: 0/1 -> 1/1 truthful undo.
    if (!changedPixels) {
        showToast('Color range did not change the selection');
        return false;
    }
    pushUndo(selectedZoneIndex);
    zone.regionMask = nextMask;
    refreshSelectionModifierResult();
    showToast(`Color range: ${matchedPixels.toLocaleString()} matched · ${mode}`);
    return true;
}

